    public static bool operator <(PowerDensity? a, PowerDensity b) => a.HasValue && a.GetValueOrDefault() < b;
    public static bool operator >(PowerDensity? a, PowerDensity b) => a.HasValue && a.GetValueOrDefault() > b;
    public static bool operator <=(PowerDensity? a, PowerDensity b) => a.HasValue && a.GetValueOrDefault() <= b;
    public static bool operator >=(PowerDensity? a, PowerDensity b) => a.HasValue && a.GetValueOrDefault() >= b;
    public static bool operator <(PowerDensity a, PowerDensity? b) => b.HasValue && a < b.GetValueOrDefault();
    public static bool operator >(PowerDensity a, PowerDensity? b) => b.HasValue && a > b.GetValueOrDefault();
    public static bool operator <=(PowerDensity a, PowerDensity? b) => b.HasValue && a <= b.GetValueOrDefault();
    public static bool operator >=(PowerDensity a, PowerDensity? b) => b.HasValue && a >= b.GetValueOrDefault();

    // ---- Conversions ----
    public static implicit operator UnknownUnit(PowerDensity value) => new(value._si);
    /// <summary>Free at runtime - the analyzer checks the dimension at compile time (EUF0001).</summary>
    public static implicit operator PowerDensity(UnknownUnit value) => new(value.SI);
    // Deliberately NO implicit PowerDensity(UnknownUnit?): the null literal converts to UnknownUnit?, so "Power p = null;" would
    // compile and throw, and "cond ? x : null" would throw instead of being null. (The analyzer caught this.)

    // ---- Alias: PressureChangeRate has the same dimension ----
    // Explicit: same dimension doesn't always mean the same thing (Torque vs Energy)
    public static explicit operator PowerDensity(PressureChangeRate value) => new(value.SI);
    public static PowerDensity operator +(PowerDensity a, PressureChangeRate b) => new(a._si + b.SI);
    public static PowerDensity operator -(PowerDensity a, PressureChangeRate b) => new(a._si - b.SI);
    public static bool operator ==(PowerDensity a, PressureChangeRate b) => SIComparison.Equal(a._si, b.SI);
    public static bool operator !=(PowerDensity a, PressureChangeRate b) => !SIComparison.Equal(a._si, b.SI);
    public static bool operator <(PowerDensity a, PressureChangeRate b) => SIComparison.Less(a._si, b.SI);
    public static bool operator >(PowerDensity a, PressureChangeRate b) => SIComparison.Greater(a._si, b.SI);
    public static bool operator <=(PowerDensity a, PressureChangeRate b) => SIComparison.LessOrEqual(a._si, b.SI);
    public static bool operator >=(PowerDensity a, PressureChangeRate b) => SIComparison.GreaterOrEqual(a._si, b.SI);
    // Same dimension, so PressureChangeRate's units work too - like EngineeringUnits' As(UnitSystem)
    public double As(PressureChangeRateUnit unit) => unit.FromSI(_si);
    public QuantityInUnit<PowerDensity> ToUnit(PressureChangeRateUnit unit) => new(this, unit);
    public string ToString(PressureChangeRateUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    // ---- Helpers - same names and behaviour as EngineeringUnits ----
    public PowerDensity Abs() => new(Math.Abs(_si));
    /// <summary>Limits the value to [min, max]. Like EngineeringUnits: if max &lt; min the value is returned unchanged.</summary>
    public PowerDensity Clamp(PowerDensity min, PowerDensity max) => max._si < min._si ? this : new(Math.Min(Math.Max(_si, min._si), max._si));
    /// <summary>Like EngineeringUnits: a null limit is no limit.</summary>
    public PowerDensity Clamp(PowerDensity? min, PowerDensity? max) => (min, max) switch
    {
        (null, null) => this,
        (null, { } hi) => _si > hi._si ? hi : this,
        ({ } lo, null) => _si < lo._si ? lo : this,
        ({ } lo, { } hi) => Clamp(lo, hi),
    };
    public PowerDensity LowerLimitAt(PowerDensity limit) => _si > limit._si ? this : limit;
    public PowerDensity UpperLimitAt(PowerDensity limit) => _si < limit._si ? this : limit;
    /// <summary>Rounds to a multiple of <paramref name="step"/> (midpoints to even, like Math.Round).</summary>
    public PowerDensity RoundTo(PowerDensity step) => new(Math.Round(_si / step._si) * step._si);
    public PowerDensity CeilingTo(PowerDensity step) => new(Math.Ceiling(_si / step._si) * step._si);
    public PowerDensity FloorTo(PowerDensity step) => new(Math.Floor(_si / step._si) * step._si);
    public bool IsZero() => _si == 0;
    public bool IsNotZero() => !IsZero();
    public bool IsAboveZero() => _si > 0;
    public bool IsBelowZero() => _si < 0;
    /// <summary>Not NaN and not infinite, like EngineeringUnits.</summary>
    public bool HasValue() => !double.IsNaN(_si) && !double.IsInfinity(_si);
    public bool HasNoValue() => !HasValue();
    /// <summary>A PowerDensity is never null - returns itself. The PowerDensity? version returns Zero for null.</summary>
    public PowerDensity IfNullSetToZero() => this;
    public static PowerDensity Min(PowerDensity a, PowerDensity b) => a._si <= b._si ? a : b;
    public static PowerDensity Max(PowerDensity a, PowerDensity b) => a._si >= b._si ? a : b;
    /// <summary>
    /// == with your own tolerance. == itself already allows 1e-12 (relative), so 1 ft == 12 in is true
    /// even though the doubles differ in the last bit.
    /// </summary>
    public bool IsCloseTo(PowerDensity other, double relativeTolerance = SIComparison.RelativeTolerance)
        => SIComparison.Equal(_si, other._si, relativeTolerance);
    public bool IsNaN() => double.IsNaN(_si);
    public bool IsInfinity() => double.IsInfinity(_si);

    // ---- Equality ----
    public bool Equals(PowerDensity other) => _si.Equals(other._si);
    public override bool Equals(object? obj) => obj is PowerDensity other && Equals(other);
    public override int GetHashCode() => _si.GetHashCode();
    public int CompareTo(PowerDensity other) => _si.CompareTo(other._si);
    public int CompareTo(object? obj) => obj is PowerDensity other ? CompareTo(other) : throw new ArgumentException($"Can't compare PowerDensity with {obj?.GetType().Name ?? "null"}");

    // ---- Text ----
    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, PowerDensityUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(PowerDensityUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to PowerDensity, but math on it needs the PowerDensity first.
    /// </summary>
    public QuantityInUnit<PowerDensity> ToUnit(PowerDensityUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public PowerDensity ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "W/m³"}. Reads that (any unit of PowerDensity, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class PowerDensityJsonConverter : JsonConverter<PowerDensity>
{
    public override PowerDensity Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => PowerDensity.FromSI(QuantityJson.Read(ref reader, "PowerDensity", PowerDensityUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, PowerDensity value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, PowerDensityUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this PowerDensity value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this PowerDensity value) => new(Math.Sqrt(value.SI));

    public static PowerDensity Sum(this IEnumerable<PowerDensity> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return PowerDensity.FromSI(sum);
    }

    public static PowerDensity Average(this IEnumerable<PowerDensity> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : PowerDensity.FromSI(sum / count);
    }

    public static PowerDensity Min(this IEnumerable<PowerDensity> values) => Aggregate(values, Math.Min);
    public static PowerDensity Max(this IEnumerable<PowerDensity> values) => Aggregate(values, Math.Max);

    private static PowerDensity Aggregate(IEnumerable<PowerDensity> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return PowerDensity.FromSI(result);
    }
}
